begin;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id, email) values ('00000000-0000-0000-0000-000000000011', 'invariants@example.invalid');
create temporary table ids(name text primary key, id uuid not null);
grant all on ids to authenticated;
create function pg_temp.f(n text) returns uuid language sql as $$ select id from ids where name = n $$;
set local role authenticated;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000011', true);
insert into ids values ('p', public.create_project('Invariant tests'));
insert into ids values ('e', public.create_experiment(pg_temp.f('p'), 1, 'Experiment', 'H', 'C', 'R', 'P'));
insert into ids select 'v', current_revision_id from public.experiments where id = pg_temp.f('e');
insert into ids values ('m', public.define_metric(pg_temp.f('p'), 'Metric', 1, 'ratio', 'higher'));
insert into ids values ('c', public.create_comparison_context(pg_temp.f('p'), 'Condition A', 'dataset', 'split', 'eval-a', 10, jsonb_build_array(jsonb_build_object('metric_id', pg_temp.f('m')))));
insert into ids values ('c2', public.create_comparison_context(pg_temp.f('p'), 'Condition B', 'dataset', 'split', 'eval-b', 10, jsonb_build_array(jsonb_build_object('metric_id', pg_temp.f('m')))));
insert into ids values ('g', public.create_run_group(pg_temp.f('p'), pg_temp.f('e'), pg_temp.f('v'), pg_temp.f('c'), 2));
insert into ids values ('missing', public.record_run(pg_temp.f('p'), pg_temp.f('g'), 'missing', 1, 1, 'succeeded', 'missing-output', '[]'));
select throws_ok(format('select public.finalize_run_group(%L, %L, %L, %L, ''Review'')', pg_temp.f('p'), pg_temp.f('g'), jsonb_build_array(jsonb_build_object('repetition', 1, 'run_id', pg_temp.f('missing'))), jsonb_build_array(jsonb_build_object('repetition', 2, 'reason', 'Not available'))), '23514', 'Selections require compatible successful runs and all required metrics', 'Required missing metric prevents finalization');
insert into ids values ('r1', public.record_run(pg_temp.f('p'), pg_temp.f('g'), 'r1', 1, 2, 'succeeded', 'same-output', jsonb_build_array(jsonb_build_object('metric_id', pg_temp.f('m'), 'state', 'measured', 'value', 0))));
insert into ids values ('r2', public.record_run(pg_temp.f('p'), pg_temp.f('g'), 'r2', 2, 1, 'succeeded', 'same-output', jsonb_build_array(jsonb_build_object('metric_id', pg_temp.f('m'), 'state', 'measured', 'value', 0.5))));
select throws_ok(format('select public.finalize_run_group(%L, %L, %L, ''[]'', ''Review'')', pg_temp.f('p'), pg_temp.f('g'), jsonb_build_array(jsonb_build_object('repetition', 1, 'run_id', pg_temp.f('r1')), jsonb_build_object('repetition', 2, 'run_id', pg_temp.f('r2')))), '23514', 'The same generation output cannot count as independent repetitions', 'Same generation evaluated twice is not two independent samples');
select throws_ok(format('select public.finalize_run_group(%L, %L, %L, %L, ''Review'')', pg_temp.f('p'), pg_temp.f('g'), jsonb_build_array(jsonb_build_object('repetition', 1, 'run_id', pg_temp.f('r1'))), jsonb_build_array(jsonb_build_object('repetition', 1, 'reason', 'Overlap'))), '23514', 'Repetition already selected', 'A repetition cannot be selected and excluded');
select lives_ok(format('select public.finalize_run_group(%L, %L, %L, %L, ''Review'')', pg_temp.f('p'), pg_temp.f('g'), jsonb_build_array(jsonb_build_object('repetition', 1, 'run_id', pg_temp.f('r1'))), jsonb_build_array(jsonb_build_object('repetition', 2, 'reason', 'Same generation'))), 'One selection and explained exclusion is valid');
select is((select stddev from public.run_group_metric_summaries where group_id = pg_temp.f('g')), null::float8, 'Single-sample standard deviation is null');
select is((select mean from public.run_group_metric_summaries where group_id = pg_temp.f('g')), 0::float8, 'Measured zero remains zero');
insert into ids values ('g2', public.create_run_group(pg_temp.f('p'), pg_temp.f('e'), pg_temp.f('v'), pg_temp.f('c2'), 1));
select throws_ok(format('select public.finalize_run_group(%L, %L, %L, ''[]'', ''Wrong context'')', pg_temp.f('p'), pg_temp.f('g2'), jsonb_build_array(jsonb_build_object('repetition', 1, 'run_id', pg_temp.f('r1')))), '23514', 'Selections require compatible successful runs and all required metrics', 'Different evaluation context cannot be mixed');
insert into ids values ('r3', public.record_run(pg_temp.f('p'), pg_temp.f('g2'), 'r3', 1, 1, 'succeeded', 'third-output', jsonb_build_array(jsonb_build_object('metric_id', pg_temp.f('m'), 'state', 'measured', 'value', 0.8))));
select lives_ok(format('select public.finalize_run_group(%L, %L, %L, ''[]'', ''Review'')', pg_temp.f('p'), pg_temp.f('g2'), jsonb_build_array(jsonb_build_object('repetition', 1, 'run_id', pg_temp.f('r3')))), 'Second group finalized');
select public.set_representative_result(pg_temp.f('p'), pg_temp.f('e'), pg_temp.f('g'), 'First selection');
select public.set_representative_result(pg_temp.f('p'), pg_temp.f('e'), pg_temp.f('g2'), 'New evaluation selection');
select ok(exists(select 1 from public.audit_events where entity_id = pg_temp.f('e')::text and reason = 'New evaluation selection'
  and details ->> 'previous_group_id' = pg_temp.f('g')::text and details ->> 'group_id' = pg_temp.f('g2')::text
  and details ->> 'previous_context_id' = pg_temp.f('c')::text and details ->> 'context_id' = pg_temp.f('c2')::text), 'Representative replacement retains both group/context references and reason');
insert into ids values ('reported', public.create_baseline_version(pg_temp.f('p'), 'External', 'reported', 'Reference only', p_source => 'Synthetic citation', p_metrics => jsonb_build_array(jsonb_build_object('metric_id', pg_temp.f('m'), 'mean', 0))));
select is((select context_id from public.baseline_versions where id = pg_temp.f('reported')), null::uuid, 'Unknown comparison context stays unclassified');
select throws_like(format('select public.create_baseline_version(%L, ''Invalid external'', ''reported'', ''Reason'')', pg_temp.f('p')), '%check constraint%', 'Reported baseline requires source');
select throws_like(format('select public.create_baseline_version(%L, ''Invalid sample'', ''reported'', ''Reason'', p_source => ''Source'', p_metrics => %L)', pg_temp.f('p'), jsonb_build_array(jsonb_build_object('metric_id', pg_temp.f('m'), 'mean', 0.2, 'stddev', 0.1, 'sample_count', 1))), '%check constraint%', 'Reported single sample cannot claim sample standard deviation');
insert into ids values ('reuse', public.create_run_group(pg_temp.f('p'), pg_temp.f('e'), pg_temp.f('v'), pg_temp.f('c'), 1));
select lives_ok(format('select public.finalize_run_group(%L, %L, %L, ''[]'', ''Reuse prior compatible evaluation'')', pg_temp.f('p'), pg_temp.f('reuse'), jsonb_build_array(jsonb_build_object('repetition', 1, 'run_id', pg_temp.f('r1')))), 'New group can reference a compatible prior evaluation');
reset role;
select throws_ok(format('insert into public.run_metrics(project_id, run_id, context_id, metric_definition_id, state, value) values (%L, %L, %L, %L, ''measured'', 0.9)', pg_temp.f('p'), pg_temp.f('r1'), pg_temp.f('c'), pg_temp.f('m')), '23514', 'Finalized metrics cannot change', 'Privileged metric appends cannot affect finalized selections');
select * from finish();
rollback;
